def longest_common_prefix(strs):
    if not strs:
        return ""
    prefix = strs[0]
    for s in strs[1:]:
        i = 0
        while i < len(prefix) and i < len(s) and prefix[i] == s[i]:
            i += 1
        prefix = prefix[:i]
        if not prefix:
            break
    return prefix

def longest_common_suffix(strs):
    if not strs:
        return ""
    suffix = strs[0]
    for s in strs[1:]:
        i = 0
        while i < len(suffix) and i < len(s) and suffix[-1 - i] == s[-1 - i]:
            i += 1
        suffix = suffix[len(suffix) - i:] if i > 0 else ""
        if not suffix:
            break
    return suffix

def common_prefix_length(a, b):
    i = 0
    while i < len(a) and i < len(b) and a[i] == b[i]:
        i += 1
    return i

def common_suffix_length(a, b):
    i = 0
    while i < len(a) and i < len(b) and a[-1 - i] == b[-1 - i]:
        i += 1
    return i

def first_difference_index(a, b):
    n = min(len(a), len(b))
    for i in range(n):
        if a[i] != b[i]:
            return i
    if len(a) == len(b):
        return -1
    return n

def is_one_edit_away(a, b):
    la, lb = len(a), len(b)
    if abs(la - lb) > 1:
        return False
    if la == lb:
        diffs = sum(1 for x, y in zip(a, b) if x != y)
        return diffs <= 1
    if la > lb:
        a, b = b, a
        la, lb = lb, la
    i = j = 0
    found_diff = False
    while i < la and j < lb:
        if a[i] != b[j]:
            if found_diff:
                return False
            found_diff = True
            j += 1
        else:
            i += 1
            j += 1
    return True

def char_count_difference(a, b):
    from collections import Counter
    ca, cb = Counter(a), Counter(b)
    keys = set(ca) | set(cb)
    return sum(abs(ca[k] - cb[k]) for k in keys)

def count_substring_occurrences_overlapping(s, sub):
    if not sub:
        return 0
    count = 0
    start = 0
    while True:
        idx = s.find(sub, start)
        if idx == -1:
            break
        count += 1
        start = idx + 1
    return count

def count_substring_occurrences_nonoverlapping(s, sub):
    if not sub:
        return 0
    count = 0
    start = 0
    while True:
        idx = s.find(sub, start)
        if idx == -1:
            break
        count += 1
        start = idx + len(sub)
    return count

def find_all_occurrence_indices(s, sub):
    if not sub:
        return []
    indices = []
    start = 0
    while True:
        idx = s.find(sub, start)
        if idx == -1:
            break
        indices.append(idx)
        start = idx + 1
    return indices

def longest_border_length(s):
    n = len(s)
    if n == 0:
        return 0
    fail = [0] * n
    for i in range(1, n):
        j = fail[i - 1]
        while j > 0 and s[i] != s[j]:
            j = fail[j - 1]
        if s[i] == s[j]:
            j += 1
        fail[i] = j
    return fail[-1]

def shortest_distinguishing_prefix_length(a, b):
    i = 0
    while i < len(a) and i < len(b) and a[i] == b[i]:
        i += 1
    if i == len(a):
        return len(a)
    return i + 1

def trim_matching_ends(s, ch):
    i, j = 0, len(s)
    while i < j and s[i] == ch:
        i += 1
    while j > i and s[j - 1] == ch:
        j -= 1
    return s[i:j]

def classify_char_string(s):
    vowels = set("aeiouAEIOU")
    result = []
    for c in s:
        if c.isalpha():
            result.append('V' if c in vowels else 'C')
        elif c.isdigit():
            result.append('D')
        else:
            result.append('O')
    return "".join(result)

def shift_digits_in_string(s, k):
    result = []
    for c in s:
        if c.isdigit():
            result.append(str((int(c) + k) % 10))
        else:
            result.append(c)
    return "".join(result)

def replace_vowels_with_symbol(s, symbol):
    vowels = set("aeiouAEIOU")
    return "".join(symbol if c in vowels else c for c in s)
